SET NAMES utf8mb4;
SET time_zone = '+00:00';
CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, role ENUM('admin','staff','customer') NOT NULL, full_name VARCHAR(160) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password_hash VARCHAR(255) NULL, insured_id BIGINT UNSIGNED NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, email_verified_at DATETIME NULL, last_login_at DATETIME NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_users_role_active(role,is_active), KEY idx_users_insured(insured_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS insureds (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, legal_name VARCHAR(180) NOT NULL, dba_name VARCHAR(180) NULL, dot_number VARCHAR(24) NOT NULL UNIQUE, email VARCHAR(254) NULL, phone VARCHAR(50) NULL, address_line1 VARCHAR(180) NULL, address_line2 VARCHAR(180) NULL, city VARCHAR(100) NULL, state VARCHAR(80) NULL, postal_code VARCHAR(20) NULL, country VARCHAR(80) NOT NULL DEFAULT 'USA', status ENUM('active','inactive') NOT NULL DEFAULT 'active', notes TEXT NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_insureds_name(legal_name), KEY idx_insureds_email(email)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS vehicles (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, insured_id BIGINT UNSIGNED NOT NULL, vin VARCHAR(50) NOT NULL UNIQUE, unit_number VARCHAR(40) NULL, vehicle_type VARCHAR(80) NULL, make VARCHAR(80) NULL, model VARCHAR(80) NULL, model_year SMALLINT UNSIGNED NULL, value_amount DECIMAL(12,2) NULL, status ENUM('active','inactive') NOT NULL DEFAULT 'active', notes TEXT NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_vehicles_insured(insured_id), CONSTRAINT fk_vehicles_insured FOREIGN KEY(insured_id) REFERENCES insureds(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS policies (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, insured_id BIGINT UNSIGNED NOT NULL, policy_number VARCHAR(100) NOT NULL UNIQUE, carrier_name VARCHAR(180) NULL, business_line VARCHAR(100) NULL, broker_name VARCHAR(180) NULL, finance_company VARCHAR(180) NULL, effective_date DATE NULL, expiration_date DATE NULL, written_premium DECIMAL(13,2) NULL, estimated_fee DECIMAL(13,2) NULL, estimated_tax DECIMAL(13,2) NULL, total_premium DECIMAL(13,2) NULL, status ENUM('draft','active','expired','cancelled') NOT NULL DEFAULT 'draft', certificate_number VARCHAR(100) NULL, revision_number VARCHAR(40) NULL, coverage_data JSON NULL, notes TEXT NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_policies_insured_status(insured_id,status), KEY idx_policies_dates(effective_date,expiration_date), CONSTRAINT fk_policies_insured FOREIGN KEY(insured_id) REFERENCES insureds(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS policy_vehicles (policy_id BIGINT UNSIGNED NOT NULL, vehicle_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(policy_id,vehicle_id), CONSTRAINT fk_pv_policy FOREIGN KEY(policy_id) REFERENCES policies(id) ON DELETE CASCADE, CONSTRAINT fk_pv_vehicle FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS drivers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, insured_id BIGINT UNSIGNED NOT NULL, full_name VARCHAR(180) NOT NULL, license_number VARCHAR(100) NULL, license_state VARCHAR(80) NULL, date_of_birth DATE NULL, is_excluded TINYINT(1) NOT NULL DEFAULT 0, status ENUM('active','inactive') NOT NULL DEFAULT 'active', notes TEXT NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_drivers_insured(insured_id), KEY idx_drivers_license(license_number,license_state), CONSTRAINT fk_drivers_insured FOREIGN KEY(insured_id) REFERENCES insureds(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS policy_drivers (policy_id BIGINT UNSIGNED NOT NULL, driver_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(policy_id,driver_id), CONSTRAINT fk_pd_policy FOREIGN KEY(policy_id) REFERENCES policies(id) ON DELETE CASCADE, CONSTRAINT fk_pd_driver FOREIGN KEY(driver_id) REFERENCES drivers(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, insured_id BIGINT UNSIGNED NOT NULL, policy_id BIGINT UNSIGNED NULL, transaction_type VARCHAR(80) NOT NULL DEFAULT 'other', transaction_date DATE NULL, amount DECIMAL(13,2) NULL, reference_number VARCHAR(100) NULL, status VARCHAR(40) NOT NULL DEFAULT 'pending', description TEXT NULL, extra_data JSON NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_transactions_insured_date(insured_id,transaction_date), CONSTRAINT fk_transactions_insured FOREIGN KEY(insured_id) REFERENCES insureds(id) ON DELETE RESTRICT, CONSTRAINT fk_transactions_policy FOREIGN KEY(policy_id) REFERENCES policies(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS claims (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, insured_id BIGINT UNSIGNED NOT NULL, policy_id BIGINT UNSIGNED NULL, claim_number VARCHAR(100) NULL, claim_date DATE NULL, incident_date DATE NULL, claim_type VARCHAR(100) NULL, status VARCHAR(50) NOT NULL DEFAULT 'open', loss_amount DECIMAL(13,2) NULL, description TEXT NULL, extra_data JSON NULL, created_by BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_claims_insured_status(insured_id,status), KEY idx_claims_number(claim_number), CONSTRAINT fk_claims_insured FOREIGN KEY(insured_id) REFERENCES insureds(id) ON DELETE RESTRICT, CONSTRAINT fk_claims_policy FOREIGN KEY(policy_id) REFERENCES policies(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_user_id BIGINT UNSIGNED NULL, actor_role VARCHAR(30) NULL, action VARCHAR(80) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id BIGINT UNSIGNED NULL, summary VARCHAR(500) NOT NULL, ip_address VARCHAR(45) NULL, user_agent VARCHAR(500) NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_audit_created(created_at), KEY idx_audit_actor(actor_user_id,created_at), KEY idx_audit_entity(entity_type,entity_id), CONSTRAINT fk_audit_actor FOREIGN KEY(actor_user_id) REFERENCES users(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS signup_verifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, insured_id BIGINT UNSIGNED NOT NULL, email VARCHAR(254) NOT NULL, code_hash VARCHAR(255) NOT NULL, expires_at DATETIME NOT NULL, attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, verified_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_signup_email_expiry(email,expires_at), CONSTRAINT fk_signup_insured FOREIGN KEY(insured_id) REFERENCES insureds(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash VARCHAR(255) NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_password_reset_user(user_id,expires_at), CONSTRAINT fk_password_reset_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;